SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
BEGIN TRAN
  SELECT * FROM Orders WHERE Amount > 1000;
  -- (Holds Shared Locks on existing rows)
  -- ... Wait ...
  SELECT * FROM Orders WHERE Amount > 1000;
COMMIT

-- Setup: ALTER DATABASE MyDB SET ALLOW_SNAPSHOT_ISOLATION ON;

-- Transaction A (Session 1)
SET TRANSACTION ISOLATION LEVEL SNAPSHOT;
BEGIN TRAN;
    DECLARE @Qty INT;
    SELECT @Qty = Quantity FROM Products WHERE ProductID = 101; -- Reads 10
    -- (Pauses here for a few seconds)

-- Transaction B (Session 2)
BEGIN TRAN;
    UPDATE Products SET Quantity = 5 WHERE ProductID = 101;
COMMIT;

-- Transaction A (Session 1 resumes)
    UPDATE Products SET Quantity = @Qty - 1 WHERE ProductID = 101;
COMMIT;
